`timescale 1ns/1ps
// Basys 3 top level - generated by scripts/make_experiments.py
module top_basys3 (
    input  wire        clk,                    // 100 MHz
    input  wire        btnC, btnU, btnL, btnR, // btnC = reset
    input  wire [15:0] sw,
    output wire [15:0] led,
    output wire [3:0]  an,
    output wire [6:0]  seg
);
    wire rst = btnC;
    wire en;   // one model step every 1/50 s, slow enough to watch
    step_tick #(.STEP_HZ(50)) u_tick (.clk(clk), .rst(rst), .tick(en));
    // pre-synaptic spikes: press btnU, or sw[0] = regular train, one spike every (4 + 2*sw[3:1]) steps
    wire press;  btn_pulse u_b (.clk(clk), .rst(rst), .tick(en), .btn(btnU), .pulse(press));
    reg [4:0] cnt;
    always @(posedge clk) if (rst) cnt <= 0; else if (en) cnt <= (cnt >= 4 + 2*sw[3:1]) ? 0 : cnt + 1;
    wire pre = press | (en & sw[0] & (cnt == 0));
    wire signed [31:0] xd, ud, id, xf, uf, i_f;
    tm_synapse #(.U(32768), .TAU_REC(7), .TAU_FAC(2)) u_dep (.clk(clk), .rst(rst), .en(en), .pre_spike(pre), .x(xd), .u(ud), .i_syn(id));
    tm_synapse #(.U(6554),  .TAU_REC(3), .TAU_FAC(7)) u_fac (.clk(clk), .rst(rst), .en(en), .pre_spike(pre), .x(xf), .u(uf), .i_syn(i_f));
    wire signed [31:0] i_syn = sw[15] ? i_f : id;
    wire spike_led;
    pulse_stretch u_ps (.clk(clk), .rst(rst), .in(pre), .out(spike_led));
    wire signed [31:0] bar_val = i_syn >>> 8;
    bar15 #(.FULL(12)) u_bar (.val(bar_val), .leds(led[14:0]));
    assign led[15] = spike_led;
    wire signed [31:0] num = i_syn >>> 8;
    seg7_signed u_seg (.clk(clk), .value(num[15:0]), .an(an), .seg(seg));
endmodule
